// 1. Cat cac bit cho phep ngat tu ctrl_reg (0x00C)                                                                                                                                                                                  
    wire rx_ie = ctrl_reg[1];                                                                                                                                                                                                            
    wire tx_ie = ctrl_reg[2];                                                                                                                                                                                                            
                                                                                                                                                                                                                                         
    // 2. Tao tin hieu ngat                                                                                                                                                                                                              
    wire rx_irq = rx_done && rx_ie; // Co byte den VA CPU cho phep ngat                                                                                                                                                                  
    wire tx_irq = tx_done && tx_ie; // Truyen xong VA CPU cho phep ngat                                                                                                                                                                  
                                                                                                                                                                                                                                         
    // 3. Tong hop thanh 1 duong ngat duy nhat ra ngoai chip                                                                                                                                                                             
    output wire uart_irq;                                                                                                                                                                                                                
    assign uart_irq = rx_irq | tx_irq; 